# -- operations -----------------------------------------------------

def handle(self, req):
    if type(req) is not dict:
        raise Invalid()
    op = req.get('op')
    if op == 'about':
        _fields(req, {'op'})
        return {'status': 'ok', 'protocol': 'forest-controller/3'}
    if op == 'load':
        return self.op_load(req)
    if op == 'audit':
        return self.op_audit(req)
    if op == 'advance':
        return self.op_advance(req)
    if op == 'edit':
        return self.op_edit(req)
    if op == 'prepare':
        return self.op_prepare(req)
    if op == 'commit':
        return self.op_commit(req)
    if op == 'cancel':
        return self.op_cancel(req)
    raise Invalid()

def op_load(self, req):
    _fields(req, {'op', 'n', 'links', 'bookings'})
    n = _rng(req['n'], 2, 48)
    links = req['links']
    if not isinstance(links, list) or len(links) > 128:
        raise Invalid()
    uv = []
    cap = []
    seen = set()
    for item in links:
        if not isinstance(item, list) or len(item) != 3:
            raise Invalid()
        u = _rng(item[0], 0, 47)
        v = _rng(item[1], 0, 47)
        c = _rng(item[2], 0, MAXRATE)
        if u >= n or v >= n or u == v:
            raise Invalid()
        key = (u, v) if u < v else (v, u)
        if key in seen:
            raise Invalid()
        seen.add(key)
        uv.append((u, v))
        cap.append(c)
    bookings = req['bookings']
    if not isinstance(bookings, list) or len(bookings) > 128:
        raise Invalid()
    bl = []
    ids = set()
    total = 0
    for b in bookings:
        if not isinstance(b, dict) or set(b.keys()) != {'id', 'owner', 'window', 'envelope'}:
            raise Invalid()
        bid = _sid(b['id'])
        owner = _sid(b['owner'])
        s, e = _window(b['window'])
        env = _envelope(b['envelope'])
        for l in env:
            if l >= len(uv):
                raise Invalid()
        if bid in ids:
            raise Invalid()
        ids.add(bid)
        total += len(env)
        bl.append((bid, owner, s, e, env))
    if total > 2048:
        raise Invalid()
    if self.loaded:
        return _err('ALREADY_LOADED', self.rev)
    for l in range(len(uv)):
        events = []
        for (bid, owner, s, e, env) in bl:
            rr = env.get(l, 0)
            if rr:
                events.append((s, rr))
                events.append((e, -rr))
        events.sort()
        cur = 0
        for (t, d) in events:
            cur += d
            if cur > cap[l]:
                raise Invalid()
    self.loaded = True
    self.n = n
    self.linkuv = uv
    self.linkcap = cap
    self.rev = 0
    self.now = 0
    self.leases = {}
    self.load_ids = set(ids)
    self.prep = {}
    for (bid, owner, s, e, env) in bl:
        self.leases[bid] = {'owner': owner, 's': s, 'e': e, 'env': dict(env), 'state': 'live'}
    return {'status': 'ok', 'rev': 0, 'now': 0}

